mapper.update:
UPDATE users
SET login_fail_count = #{loginFailCount},
    locked_at = #{lockedAt}
WHERE user_id = #{userId}

UPDATE users
SET login_fail_count = 0,
    locked_at = NULL,
    last_login_at = #{audit.now}
WHERE user_id = #{userId}

UPDATE users
SET email = #{email},
    phone = #{phone}
WHERE user_id = #{userId}
